const rows = $input.all().map(i => i.json);

// تجميع إحصائيات القطع/الركائز/المنصات/الأوقات
const byPage = {};
const byPillar = {};
const byPlatform = {};
const byHour = {};

rows.forEach(r => {
  const page = r.page || 'unknown';
  const pillar = r.pillar || 'unknown';
  const platform = r.source || 'unknown';
  const hour = (r.publish_hour ?? 10).toString();

  (byPage[page] ??= { sessions: 0, users: 0, pageviews: 0, engagement: 0, conversions: 0, count: 0 });
  const p = byPage[page];
  p.sessions += +r.sessions || 0;
  p.users += +r.users || 0;
  p.pageviews += +r.pageviews || 0;
  p.engagement += +(r.engagement_rate || 0);
  p.conversions += +r.conversions || 0;
  p.count++;

  (byPillar[pillar] ??= { pageviews: 0, count: 0 });
  byPillar[pillar].pageviews += +r.pageviews || 0;
  byPillar[pillar].count++;

  (byPlatform[platform] ??= { pageviews: 0, engagement: 0, count: 0 });
  byPlatform[platform].pageviews += +r.pageviews || 0;
  byPlatform[platform].engagement += +(r.engagement_rate || 0);
  byPlatform[platform].count++;

  (byHour[hour] ??= { pageviews: 0, count: 0 });
  byHour[hour].pageviews += +r.pageviews || 0;
  byHour[hour].count++;
});

const topPages = Object.entries(byPage).sort((a, b) => b[1].pageviews - a[1].pageviews).slice(0, 5);
const weakPages = Object.entries(byPage).sort((a, b) => a[1].pageviews - b[1].pageviews).slice(0, 5);

return [{
  json: {
    period: $now.toFormat('yyyy-MM-dd'),
    total_rows: rows.length,
    summary: {
      top_pages: topPages,
      weak_pages: weakPages,
      pillar_ranking: Object.entries(byPillar).sort((a, b) => b[1].pageviews - a[1].pageviews),
      platform_ranking: Object.entries(byPlatform).sort((a, b) => b[1].pageviews - a[1].pageviews),
      best_hours: Object.entries(byHour).sort((a, b) => b[1].pageviews - a[1].pageviews).slice(0, 3)
    }
  }
}];

const agg = $('Aggregate Stats (Code)').first().json;
const system = 'أنت محلل محتوى خبير. حلل البيانات وأجب على أسئلة الأداء. أعد JSON صالحاً فقط.';
const user = 'البيانات المجمعة: ' + JSON.stringify(agg) +
  '\nأجب: (1) ما المحتوى الأفضل ولماذا؟ (2) ما الضعيف ولماذا؟ (3) ما أفضل الموضوعات؟ (4) أفضل الركائز؟ (5) أفضل الأنواع؟ (6) أفضل المنصات؟ (7) أفضل الأوقات؟ (8) ما الذي يحتاج تحديثاً؟ (9) ما الجاهز لإعادة الاستخدام؟ (10) ما الفرص الجديدة؟' +
  '\nأعد: {"top_performers":[],"weak_performers":[],"insights":[],"pillar_ranking":[],"platform_ranking":[],"best_times":[],"needs_update":[],"repurpose_candidates":[],"opportunities":[],"recommendations":[]}. استند فقط إلى الأرقام.';
return [{ json: { task_type: 'performance_analyst', payload: { system, user } } }];

const analysis = $input.first().json;
const valid = Array.isArray(analysis.top_performers) && Array.isArray(analysis.recommendations);
if (!valid) throw new Error('Invalid analysis schema');
return [{ json: { ...analysis, period: $now.toFormat('yyyy-MM-dd'), status: 'analysed' } }];
